Get New Submissions Since Date.code:
// Get submissions for a form received on or after a date.
getSubmissions(
  // 1) Form id.
  $.data.formId,
  // 2) Filter options. query is a MongoDB-style JSON string.
  {
    query: `{"_submission_time":{"$gte":"2026-10-01"}}`,
    page_size: 500,
  }
);

Get Submissions By Field Value.code:
// Get submissions where a question has a given value.
getSubmissions($.data.formId, {
  query: JSON.stringify({ district: 'kampala', consent: 'yes' }),
  limit: 100,
});

Get Single Submission.code:
// Get one submission by form id and submission id.
getSubmission(
  // 1) Form id.
  $.data.formId,
  // 2) Submission id.
  $.data.submissionId
);

List Forms.code:
// List forms the account can see.
getForms({
  page: 1,
  page_size: 50,
});

Get Form Structure.code:
// Get a form's structure (questions and choices) rather than its metadata.
getForm($.data.formId, {
  structureOnly: true,
});

Download Attachment As Base64.code:
// Download an attachment as a base64 string.
downloadAttachment(
  // 1) Attachment id.
  $.data.attachmentId,
  // 2) Options: the attachment's filename and output format.
  {
    filename: $.data.attachmentFilename, // e.g. 'project/attachments/photo_1.jpg'
    parseAs: 'base64',
  }
);
